<?php require_once '../includes/auth.php'; require_role('shop'); $page_title='Sales Billing'; $uid=(int)$_SESSION['user_id'];
if(isset($_POST['sale'])){ $pid=(int)$_POST['product_id']; $qty=(int)$_POST['qty']; $customer=clean($conn,$_POST['customer_name']); $phone=clean($conn,$_POST['customer_phone']); $p=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM products WHERE id=$pid")); $st=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM stock WHERE owner_id=$uid AND product_id=$pid AND quantity >= $qty LIMIT 1")); if(!$st){ $error='Not enough stock for this product.'; } else { $sub=$qty*$p['sale_price']; $gst=$sub*$p['gst_percent']/100; $grand=$sub+$gst; $inv='INV'.time(); mysqli_query($conn,"INSERT INTO sales(invoice_no,shop_id,customer_name,customer_phone,subtotal,gst_total,grand_total) VALUES('$inv',$uid,'$customer','$phone',$sub,$gst,$grand)"); $sid=mysqli_insert_id($conn); mysqli_query($conn,"INSERT INTO sale_items(sale_id,product_id,qty,rate,gst_percent,line_total) VALUES($sid,$pid,$qty,{$p['sale_price']},{$p['gst_percent']},$grand)"); mysqli_query($conn,"UPDATE stock SET quantity=quantity-$qty WHERE id={$st['id']}"); log_audit($conn,$uid,'Create Sale',"Invoice $inv"); redirect('invoice.php?id='.$sid); } }
include '../includes/header.php'; include '../includes/sidebar.php'; $products=mysqli_query($conn,"SELECT p.*,s.quantity FROM products p JOIN stock s ON s.product_id=p.id WHERE s.owner_id=$uid AND s.quantity>0 GROUP BY p.id"); ?>
<div class="row g-4"><div class="col-md-5"><div class="card-box"><h4>New Sales Invoice</h4><?php if(isset($error)){ ?><div class="alert alert-danger"><?php echo $error; ?></div><?php } ?><form method="POST"><input class="form-control mb-2" name="customer_name" placeholder="Customer Name" required><input class="form-control mb-2" name="customer_phone" placeholder="Phone"><select class="form-select mb-2" name="product_id"><?php while($p=mysqli_fetch_assoc($products)){ ?><option value="<?php echo $p['id']; ?>"><?php echo $p['name'].' | Stock: '.$p['quantity'].' | ₹'.$p['sale_price'].' + GST '.$p['gst_percent'].'%'; ?></option><?php } ?></select><input class="form-control mb-3" type="number" name="qty" placeholder="Quantity" required><button name="sale" class="btn btn-success">Generate Invoice</button></form></div></div><div class="col-md-7"><div class="card-box"><h5>GST Calculation</h5><p>Invoice amount = product sale price × quantity + GST amount.</p><p>HTML invoice page includes Print button. Use browser print and Save as PDF.</p></div></div></div><?php include '../includes/footer.php'; ?>
